<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['request_id']??0);$action=$_POST['action']??'';$reason=trim($_POST['reason']??'');$reviewer=(int)$_SESSION['user_id'];
 $conn->begin_transaction();try{$q=$conn->prepare('SELECT * FROM student_account_requests WHERE request_id=? FOR UPDATE');$q->bind_param('i',$id);$q->execute();$r=$q->get_result()->fetch_assoc();if(!$r||$r['request_status']!=='pending')throw new RuntimeException('Request is no longer pending.');
 if($action==='approve'){ $q=$conn->prepare('SELECT student_id FROM students WHERE lrn=? AND record_status="active"');$q->bind_param('s',$r['submitted_lrn']);$q->execute();$s=$q->get_result()->fetch_assoc();if(!$s)throw new RuntimeException('No active official student record matches this LRN. Create or verify the record first.');$sid=(int)$s['student_id'];$q=$conn->prepare('SELECT request_id FROM student_account_requests WHERE student_id=? AND request_status="approved" FOR UPDATE');$q->bind_param('i',$sid);$q->execute();if($q->get_result()->fetch_assoc())throw new RuntimeException('That student record is already linked to an approved account.');$state='approved';$q=$conn->prepare('UPDATE student_account_requests SET student_id=?,request_status=?,reviewed_by=?,reviewed_at=NOW(),rejection_reason=NULL WHERE request_id=?');$q->bind_param('isii',$sid,$state,$reviewer,$id);$q->execute();$q=$conn->prepare('UPDATE users SET account_status="active" WHERE user_id=?');$q->bind_param('i',$r['user_id']);$q->execute();audit($conn,$reviewer,'student_account_approved','student_account_request',$id,['student_id'=>$sid]);}
 elseif($action==='reject'&&$reason!==''){ $state='rejected';$q=$conn->prepare('UPDATE student_account_requests SET request_status=?,rejection_reason=?,reviewed_by=?,reviewed_at=NOW() WHERE request_id=?');$q->bind_param('ssii',$state,$reason,$reviewer,$id);$q->execute();audit($conn,$reviewer,'student_account_rejected','student_account_request',$id,['reason'=>$reason]);}
 else throw new RuntimeException('Choose approve or provide a rejection reason.');$conn->commit();flash('Request reviewed.');
 }catch(Throwable $e){$conn->rollback();flash($e instanceof RuntimeException?$e->getMessage():'Unable to review the request.','error');}go('/spi/admin/student-requests.php'); }
page_start('Student account requests');echo '<h1>Student account requests</h1><p>Compare each submission with authorized official records. Approving requires an existing active student record with the submitted LRN.</p>';
$rows=$conn->query('SELECT r.*,u.email,u.username FROM student_account_requests r JOIN users u ON u.user_id=r.user_id ORDER BY FIELD(r.request_status,"pending","approved","rejected"),r.created_at DESC');echo '<div class="tablewrap"><table><thead><tr><th>Submitted identity</th><th>Email</th><th>Submitted</th><th>Status</th><th>Review</th></tr></thead><tbody>';
while($r=$rows->fetch_assoc()){echo '<tr><td>'.e($r['submitted_lrn']).'<br>'.e(trim($r['submitted_firstname'].' '.$r['submitted_middle_name'].' '.$r['submitted_lastname'])).'</td><td>'.e($r['email']).'</td><td>'.e($r['created_at']).'</td><td>'.e($r['request_status']).'</td><td>';if($r['request_status']==='pending')echo '<form method="post" class="inline"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="request_id" value="'.(int)$r['request_id'].'"><button name="action" value="approve">Approve</button><input name="reason" placeholder="Required to reject"><button class="danger" name="action" value="reject">Reject</button></form>';else echo e($r['rejection_reason']);echo '</td></tr>'; } echo '</tbody></table></div>';page_end();
